import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"坎","description":"焦氏易林注 - 坎","frontmatter":{"title":"坎","description":"焦氏易林注 - 坎"},"headers":[],"relativePath":"zh/classics/jiaoyilin/029.md","filePath":"zh/classics/jiaoyilin/029.md"}'),l={name:"zh/classics/jiaoyilin/029.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="坎" tabindex="-1">坎 <a class="header-anchor" href="#坎" aria-label="Permalink to “坎”">​</a></h1><h3 id="坎-1" tabindex="-1">坎 <a class="header-anchor" href="#坎-1" aria-label="Permalink to “坎”">​</a></h3><h3 id="坎之乾" tabindex="-1">坎之乾 <a class="header-anchor" href="#坎之乾" aria-label="Permalink to “坎之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>太王為父，季厯孝友。文武聖明，仁德興起。孔張四國，載福綏厚。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為王、為父、為始，故曰太王。下兼用遇卦坎象。互艮為季、為時、為友，故曰季厯孝友。季厯，文王父也。伏離為文，震為武，坎為聖，艮為明，故曰文武聖明。震為仁德、為興起、為孔、為張，艮為國，震卦數四，故曰四國。震為福、為車，故曰載福也。○孔，宋元本作弘，依汲古。</p><h3 id="坎之坤" tabindex="-1">坎之坤 <a class="header-anchor" href="#坎之坤" aria-label="Permalink to “坎之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>猿墮高木，不踒手足。保我金玉，還歸其室。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《臨》。惟此全用坎象。艮猿震木，艮手震足，艮金震玉，艮室震歸。○金玉，汲古訛金生，依宋元本。</p><h3 id="坎之屯" tabindex="-1">坎之屯 <a class="header-anchor" href="#坎之屯" aria-label="Permalink to “坎之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>重耳恭敏，遇讒出處。北奔戎狄，經涉齊楚。以秦伐懷，誅殺子園，身為伯主。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎為耳，坤為重，故曰重耳。初至五正覆震，故曰讒。震為出奔，坤為北、為戎狄，故曰北奔戎狄。伏巽為齊，震為楚、為伐、為伯主，坤為誅殺、為圉、為身。○伐，汲古作伐，從宋元本。</p><h3 id="坎之蒙" tabindex="-1">坎之蒙 <a class="header-anchor" href="#坎之蒙" aria-label="Permalink to “坎之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>倚鋒據戟，傷我胸臆，耗折不息。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為鋒戟，坤為胸臆、為傷、為耗，震為息，坤死故不息。○耗，宋元本作拜，依汲古。</p><h3 id="坎之需" tabindex="-1">坎之需 <a class="header-anchor" href="#坎之需" aria-label="Permalink to “坎之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>狗冠雞步，君失其所。出門抵山，行者憂難。水灌我園，高陸為泉。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>伏《晉》。艮為狗、為冠，雞步，猶雞禍，凡烖害之神皆曰步。乾為君，坎為失，坤為門，坤上艮故曰出門抵山。震為行，震覆故難。艮為園，坎水坤水，故曰水灌我園。高陸為泉，高陸艮也。○狗冠，《五行志》：&quot;昌邑王見大白狗冠方山冠而無尾，未幾，廢&quot;，《周禮夏官校人》&quot;冬祭馬步&quot;註：馬步，謂神為馬災害者。又《地官》註：凡人物災害之神皆曰步。雞步，即五行志所謂雞禍。宋元本訛雛，依汲古。兌為雞。</p><h3 id="坎之訟" tabindex="-1">坎之訟 <a class="header-anchor" href="#坎之訟" aria-label="Permalink to “坎之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>眾鳥所翔，中有大怪。丈身長頭，為我驚憂。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>坎眾離鳥，故曰眾鳥。坎為中、為怪，乾為大，伏坤為身，坎為憂。○丈身，宋元本作爪牙，依汲古。頭，汲古作頸，依宋元本。乾首互巽為長，故曰長頭。</p><h3 id="坎之師" tabindex="-1">坎之師 <a class="header-anchor" href="#坎之師" aria-label="Permalink to “坎之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>雷行相逐，未有休息。戰於平陸，為夷所覆。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《泰》。雷，依宋元本，汲古作虎。</p><h3 id="坎之比" tabindex="-1">坎之比 <a class="header-anchor" href="#坎之比" aria-label="Permalink to “坎之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>禹鑿龍門，通利水泉。同註滄海，民得安土。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為門、為鑿，伏乾為王，故曰禹，為龍，故曰龍門。坎水坤水，故曰通利水泉。坤為海、為民、為安、為土。○土，汲古作然，依宋元本。</p><h3 id="坎之小畜" tabindex="-1">坎之小畜 <a class="header-anchor" href="#坎之小畜" aria-label="Permalink to “坎之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>堯舜仁德，養賢致福。眾英積聚，國無寇賊。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>乾為帝，故曰堯舜。乾為仁、為賢、為福，兌為食，故曰養賢。伏坤為積聚、為國，坎為賊，坎伏故無。○元本下多&quot;商人失利，來爭寶貨&quot;二句，與上文不協，依宋本、汲古刪。</p><h3 id="坎之履" tabindex="-1">坎之履 <a class="header-anchor" href="#坎之履" aria-label="Permalink to “坎之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>陸居少泉，山高無雲。車行千里，塗不污輪，渴為我怨。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏震為陸、為居、為山，坤為雲，坎為泉，坤坎皆伏，故曰少泉、曰無雲。震為車、為行，坤為千里，坎為泥塗、為輪、為污，坎下震上，故輪不污。坎為怨，艮火故渴。全用伏象。</p><h3 id="坎之泰" tabindex="-1">坎之泰 <a class="header-anchor" href="#坎之泰" aria-label="Permalink to “坎之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>朝視不明，夜不見光。暝抵空床，季女奔亡，愴然心傷。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為朝，坤黑故不明。坤為夜、為暝，故不見光。伏艮為床，兌為季女，震往故曰奔，坤為亡、為心、為憂。○首二句汲古作&quot;朝不見光，暮不見明&quot;，茲依宋元本。暝，宋作本作皆，元本作沓，茲依汲古。</p><h3 id="坎之否" tabindex="-1">坎之否 <a class="header-anchor" href="#坎之否" aria-label="Permalink to “坎之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>齊魯永國，仁聖輔德。進禮雅言，定公以安。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽齊，伏兌為魯，坤為國，乾為永，故曰齊魯永國。乾為仁聖，坤為禮，乾為言，艮為定、為安，乾為公，故曰定公以安。○永，宋元本作求，依汲古。進，汲古作造，依宋元本。《左傳定十年》：&quot;會齊侯於夾谷，孔子相，齊人鼓噪以進，孔子厯階數之，齊人服罪&quot;。</p><h3 id="坎之同人" tabindex="-1">坎之同人 <a class="header-anchor" href="#坎之同人" aria-label="Permalink to “坎之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>朿帛玄圭，君以布德。伊呂百裡，應聘輔國。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>互巽為帛，乾為玉、為圭、為玄，故曰朿帛玄圭。乾為君，伏震為音，故曰伊吾。伊，讀書聲也，為樂故曰呂。伏坤為百裡、為國，言湯、文、秦穆以璧帛聘伊尹、呂望、百裡奚為輔也。</p><h3 id="坎之大有" tabindex="-1">坎之大有 <a class="header-anchor" href="#坎之大有" aria-label="Permalink to “坎之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>棘鉤我襦，為絆所拘。靈巫拜祝，禍不成災。東山之邑，中有土服，可以饒飽。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>伏《比》。坎為棘，坤為襦，艮止故曰絆、曰拘。本卦兌為口，故曰巫祝。坤為禍災，艮為山、為邑，離位東故曰東山。艮為果蓏、為土服，服菔同，《詩小雅》：&quot;象弭魚服&quot;，《周禮素服》箋與註皆作菔是其證。土服，即蘆菔，《爾雅釋草》&quot;葖蘆萉&quot;註：&quot;萉，宜為菔，蘆菔，蕪菁屬，今俗所謂蔓菁可食。&quot;故下雲可以饒飽，坎為飽。○祝，宋本、元本作禱，依汲古。土服，汲古作肥土，依宋元本。</p><h3 id="坎之謙" tabindex="-1">坎之謙 <a class="header-anchor" href="#坎之謙" aria-label="Permalink to “坎之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>門燒屋燔，為下所殘。西行出戶，順其道里。虎卧不起，牛羊歡喜。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為門屋、為火，故燔燒。坤為下、為殘、為戶，震為行，坎西故曰西行。艮為道里、為虎，艮止故不起。坤為牛，伏兌為羊，震為喜。○里，汲古作理，依宋元本。</p><h3 id="坎之豫" tabindex="-1">坎之豫 <a class="header-anchor" href="#坎之豫" aria-label="Permalink to “坎之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>牆高蔽目，昆侖翳日。遠行無明，不見歡叔。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮為牆、為山，離為目、為日，離伏故曰翳蔽、故曰無明。震為行、為歡，艮為叔。○目，宋元本作日，日作月，今依汲古。</p><h3 id="坎之隨" tabindex="-1">坎之隨 <a class="header-anchor" href="#坎之隨" aria-label="Permalink to “坎之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>天地際會，不見內外。祖辭遣送，與世長訣。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮陽在上為天，震陽在下為地，艮震相對，故曰際會、曰內外。震為祖，道祭也。兌毀折、巽隕落，故曰與世長訣。</p><h3 id="坎之蠱" tabindex="-1">坎之蠱 <a class="header-anchor" href="#坎之蠱" aria-label="Permalink to “坎之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>深水難涉，泥塗至轂。牛罷不進，濘陷為疾。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互大坎故曰深水、曰泥塗。坎為轂，艮為牛，艮止故不進，坎陷坎疾。○泥塗，宋元本作塗難，為作我，今依汲古。</p><h3 id="坎之臨" tabindex="-1">坎之臨 <a class="header-anchor" href="#坎之臨" aria-label="Permalink to “坎之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>羊警虎狼，聳耳群聚。無益於僵，為齒所傷。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，震為警，伏艮為虎狼。兌為耳，坤為群、為聚，兌為齒、為傷。○虎狼，宋元本作狼虎，茲依汲古。第二句各本作獮猴群走，依《既濟》之《巽》校。</p><h3 id="坎之觀" tabindex="-1">坎之觀 <a class="header-anchor" href="#坎之觀" aria-label="Permalink to “坎之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>履蛇躡虺，與鬼相視。警恐失氣，如騎虎尾。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇虺，伏震在上，故曰履蛇躡虺。坤為鬼，艮為視。震為警恐，巽為臭，故曰氣，巽隕故失氣。震為騎，艮為虎、為尾。○恐，宋元本作哭，依汲古。</p><h3 id="坎之噬嗑" tabindex="-1">坎之噬嗑 <a class="header-anchor" href="#坎之噬嗑" aria-label="Permalink to “坎之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>車警人墮，兩輪脫去。行者不至，主人憂懼。締結復解，夜明為喜。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為車、為警、為人，在下故曰人墮。坎為輪，伏兌數二，故曰兩輪，坎破故脫去。震為行，坎隱伏故不至。震為主人，坎為憂、為夜，離為明，故曰夜明。《禮記》：&quot;夜明，祭月也&quot;，《左傳》：&quot;恆星不見夜明也&quot;，又《拾遺記》：&quot;炎帝時有石磷之玉，號曰夜明，以暗投水浮而不滅&quot;。○墮，汲古作傾，至作止，主人作人生，均依宋元本。</p><h3 id="坎之賁" tabindex="-1">坎之賁 <a class="header-anchor" href="#坎之賁" aria-label="Permalink to “坎之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>南販北賈，與怨為市，利得百倍。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為商賈、為南，坎為北，故曰南販北賈。坎為怨，《論語》：&quot;放於利而行多怨&quot;，伏巽為市、為利，震為百，巽為倍。○怨，汲古作喜，依宋元本。百倍，宋元本作自治，依汲古。</p><h3 id="坎之剝" tabindex="-1">坎之剝 <a class="header-anchor" href="#坎之剝" aria-label="Permalink to “坎之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>延陵適魯，觀樂太史。車轔白顛，知秦興起。卒兼其國，一統為主。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《離》。轔，汲古訛鄰，依宋元本。</p><h3 id="坎之復" tabindex="-1">坎之復 <a class="header-anchor" href="#坎之復" aria-label="Permalink to “坎之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>出門逢患，與福為怨。更相擊刺，傷我手端。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《坎》象。互艮為門，震為出，坎為患，故曰出門逢患。震為福，坎為怨，艮為擊刺，正反艮，故更相擊刺，相擊故手受傷。○患，汲古作惡，怨、更作患、反，均依宋元本。福，宋元本作禍，依汲古。</p><h3 id="坎之無妄" tabindex="-1">坎之無妄 <a class="header-anchor" href="#坎之無妄" aria-label="Permalink to “坎之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>獐鹿群走，自然燕喜。公子好游，他人多有。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為獐鹿，伏坤為群，震為走、為喜、為公、為子。○群，宋元本作同，然作燕，燕作嘉，均依汲古。</p><h3 id="坎之大畜" tabindex="-1">坎之大畜 <a class="header-anchor" href="#坎之大畜" aria-label="Permalink to “坎之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>恭寬信敏，履福不殆。從其邦域，與喜相得。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>乾為福，上震故曰履福、曰喜。艮為邦。</p><h3 id="坎之頤" tabindex="-1">坎之頤 <a class="header-anchor" href="#坎之頤" aria-label="Permalink to “坎之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>欲飛無翼，鼎重摺足。失其福利，苞羞為賊。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為飛、為翼，坤亡故無翼。震為鼎、為足，坤為重、為敗，故折足。乾為福，巽為利，乾巽皆伏，故曰失其福利。坤為羞，在中故曰苞羞。○福，宋元本作喜，依汲古。苞，汲古作庖，依宋元本。</p><h3 id="坎之大過" tabindex="-1">坎之大過 <a class="header-anchor" href="#坎之大過" aria-label="Permalink to “坎之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>府藏之富，王以賑貨。捕魚河海，罟網多得。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏《頤》。坤為府藏、為富，震為王、為賑，言王以其富賑民也。坤為魚、為河海，艮手為捕，互大離故曰罟網，坤為多。</p><h3 id="坎之坎" tabindex="-1">坎之坎 <a class="header-anchor" href="#坎之坎" aria-label="Permalink to “坎之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>有鳥黃足，歸呼季玉。從我睢陽，可避刀兵。與福俱行，有命久長。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互艮為鳥，震為足、為黃，故曰黃足。震為歸、為呼、為玉，艮為季，故曰季玉。震為從，艮為我，納丙，又為視，故曰雎陽。艮為刀兵，坎隱，故可避刀兵。○鳥黃，宋元本作黃鳥，從汲古，此似有故事。</p><h3 id="坎之離" tabindex="-1">坎之離 <a class="header-anchor" href="#坎之離" aria-label="Permalink to “坎之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>陰生麏鹿，鼠舞鬼哭。靈龜陸處，釜甑塵土。仁智盤桓，國亂無緒。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。震為鹿，艮為鼠，坎為鬼，震為哭、為釜甑、為仁，艮為龜、為鹿、為塵土、為盤桓、為國。○麏，汲古作麓，土作生，均依宋元本。處，宋元本作蒙，塵作草，均依汲古。緒，汲古作歡，茲依宋元本。</p><h3 id="坎之咸" tabindex="-1">坎之咸 <a class="header-anchor" href="#坎之咸" aria-label="Permalink to “坎之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>風塵暝迷，不見南北。行人失路，復反其室。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>伏《損》。坤為風、為迷，艮為塵，震南坤北，兌昧故不見。震為行人、為道路，坤迷故失路。艮為室，震為反。○瞑迷，汲古作坎坷，行人失路作行迷失利，茲依宋元本。</p><h3 id="坎之恒" tabindex="-1">坎之恒 <a class="header-anchor" href="#坎之恒" aria-label="Permalink to “坎之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>金革白黃，宜利戎市。嫁娶有息，商人悅喜。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。艮為金、為革，巽白震黃，故曰金革白黃。坤為戎狄，巽為利市，故曰宜利戎市。震為嫁、為商人、為喜。○戎，元本訛戒。</p><h3 id="坎之遯" tabindex="-1">坎之遯 <a class="header-anchor" href="#坎之遯" aria-label="Permalink to “坎之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>匏瓜之德，宜系不食。君子失輿，官政懷憂。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為匏瓜，巽為系，兌口為食，兌覆故不食。《論語》：&quot;吾豈匏瓜也哉，焉能系而不食&quot;。艮為君子，震為輿，震覆故失輿。艮為官。○輿，元本訛與，依汲古。政，汲古作正，依宋元本。</p><h3 id="坎之大壯" tabindex="-1">坎之大壯 <a class="header-anchor" href="#坎之大壯" aria-label="Permalink to “坎之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>乘船渡濟，載水逢火。賴得免患，我有所恃。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為船，乾為江河，故曰渡濟。伏坤為水，艮為火，故曰載水逢火。坤為患、為我。○我有，宋元本作蒙我，依汲古。</p><h3 id="坎之晉" tabindex="-1">坎之晉 <a class="header-anchor" href="#坎之晉" aria-label="Permalink to “坎之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>道險多石，傷車折軸。與市為仇，不利客宿。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為道、為石，坎險，故曰道險多石。坎為車、為軸、為多眚，故傷車折軸。艮為宿，震為客，震覆故不利。○險，宋本作途，元本作塗，依汲古。</p><h3 id="坎之明夷" tabindex="-1">坎之明夷 <a class="header-anchor" href="#坎之明夷" aria-label="Permalink to “坎之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>托寄之徒，不利請求。結衿無言，乃有悔患。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>艮為請求，艮覆故不利。震為襟，坤閉故曰結衿。震為言，坤括囊故無言。坎為患。結衿，乃罪人就刑時結朿之狀。坤為死，坎為刑，故有此象。</p><h3 id="坎之家人" tabindex="-1">坎之家人 <a class="header-anchor" href="#坎之家人" aria-label="Permalink to “坎之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>三羊爭雌，相逐犇馳。終日不食，精氣竭罷。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《大畜》。○首句汲古作三年爭妻，茲依宋元本，然卦無羊象，《易大壯上六》有羊象，上六體震，疑《易》以震為羊，茲曰三羊，似亦以伏震為羊。</p><h3 id="坎之睽" tabindex="-1">坎之睽 <a class="header-anchor" href="#坎之睽" aria-label="Permalink to “坎之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>退惡防患，見在心苗。日中之恩，解釋倒懸。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>第二句汲古無，依宋元本增。日中之恩，汲古作日之中息，依宋元本。苗應為田，與下懸韻，梁簡文帝大法頌：澤雨無偏，心田受潤。</p><h3 id="坎之蹇" tabindex="-1">坎之蹇 <a class="header-anchor" href="#坎之蹇" aria-label="Permalink to “坎之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>兩足四翼，飛入嘉國。寧我伯姊，與母相得。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《同人》。</p><h3 id="坎之解" tabindex="-1">坎之解 <a class="header-anchor" href="#坎之解" aria-label="Permalink to “坎之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>寒露所凌，漸至堅冰。草木瘡傷，華落葉亡。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎為寒、為露、為冰，又為堅，故漸至堅冰。震為草木，坎為破，故為瘡。震為花葉，伏巽為落，故葉落花亡。○所凌，宋元本作所降，漸作凌，茲依汲古。冰，宋本訛水。</p><h3 id="坎之損" tabindex="-1">坎之損 <a class="header-anchor" href="#坎之損" aria-label="Permalink to “坎之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>后稷農功，富利我國。南畝治理，一室百子。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為稷，坤為富利、為國、為畝，震為南，故曰南畝。艮為治理、為室，震為子，坤為百，故曰百子。室，實也，言農家治理菓蓏，一實之中有百子也。</p><h3 id="坎之益" tabindex="-1">坎之益 <a class="header-anchor" href="#坎之益" aria-label="Permalink to “坎之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>設網張羅，捕魚園池。網罟自決，雖得復失。危訴之患，受其忻歡。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>上巽為繩，坤中虛，艮手，故曰設網張羅。巽為魚，坤為園池，艮擊，故捕魚園池。巽為敝漏，故網決。決，絕也，網決故得而復失。坤為失、為患。末二句有訛字，義未詳。○忻，元本作低，依汲古。訴，汲古作許，依宋元本。</p><h3 id="坎之夬" tabindex="-1">坎之夬 <a class="header-anchor" href="#坎之夬" aria-label="Permalink to “坎之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>路輿縣休，侯伯恣驕。上失其威，周室衰微。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>威，宋元本作盛，依汲古。衰，汲古作相，依宋元本。輿多訛為與，路輿，大車也，見《左傳桓二年》疏。又《周禮春官》：&quot;王之五路。&quot;路車乃天子之乘，縣休不用，其衰可知。天子之所以衰，以侯伯嬌恣，不奉王命也。夬伏剝，坤為大輿，故曰路輿；艮一陽止於上，故曰縣休。震為諸侯、為威、為周，震反於上故曰驕恣，震覆故失其威，故周室衰微。坤為失，艮為室也。</p><h3 id="坎之姤" tabindex="-1">坎之姤 <a class="header-anchor" href="#坎之姤" aria-label="Permalink to “坎之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>逐走追亡，相及扶桑。復見其鄉，使我悔喪。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>伏《復》。震為逐、為走，震為桑，又為東，故及於扶桑。坤為鄉、為我、為悔、為喪。《山海經》&quot;日浴扶桑&quot;。</p><h3 id="坎之萃" tabindex="-1">坎之萃 <a class="header-anchor" href="#坎之萃" aria-label="Permalink to “坎之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>履祿綏厚，載福受祉。衰微復起，繼世久長。疾病獻麥，晉人赴告。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>通《大畜》。震為履，乾為祿、為厚、為福、為祖，巽隕落，故曰衰微。震為起，故曰衰微復起。坤為世，巽為長，坤為疾病，震為麥、為晉、為人、為告，《左傳成十年》：&quot;晉侯欲麥，使甸人獻麥，將食而卒。&quot;赴告者，赴君喪於各國也。○祿，元本作福，依宋本、汲古。福受，汲古作受福，依宋元本。獻麥，汲古作無危，宋元本作獻凌，宋本雲當作麥，從之。</p><h3 id="坎之升" tabindex="-1">坎之升 <a class="header-anchor" href="#坎之升" aria-label="Permalink to “坎之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>鰥寡孤獨，祿命苦薄。入宮無妻，武子哀悲。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤巽皆為寡，故曰孤獨。震為祿，巽為命，巽寡故苦薄。伏艮為宮，巽為妻、為入，坤喪故曰無妻。震為武、為子，坤為哀悲。武子，崔杼，杼將娶棠薑，筮得《困》三爻曰&quot;入其宮，不見其妻&quot;，後果得禍。</p><h3 id="坎之困" tabindex="-1">坎之困 <a class="header-anchor" href="#坎之困" aria-label="Permalink to “坎之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>山沒邱浮，陸為水魚。燕雀無巢，民無室廬。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《大有》。</p><h3 id="坎之井" tabindex="-1">坎之井 <a class="header-anchor" href="#坎之井" aria-label="Permalink to “坎之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>冠帶南游，與福喜期。徼於嘉國，拜位逢時。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏《噬嗑》。艮為冠，巽為帶，離為南，故冠帶南游。伏震為福喜，艮為國、為位、為時。○徼於，汲古作遨游，依宋元本。位，宋元本作為，非，依汲古。</p><h3 id="坎之革" tabindex="-1">坎之革 <a class="header-anchor" href="#坎之革" aria-label="Permalink to “坎之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>東行亡羊，失其羝牂。少女無夫，獨坐空廬。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為東，兌為羊，坤喪故亡羊。兌為少女，震為夫，坤喪故無夫。艮為坐、為廬，坤虛故曰空廬。</p><h3 id="坎之鼎" tabindex="-1">坎之鼎 <a class="header-anchor" href="#坎之鼎" aria-label="Permalink to “坎之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>探雀捕魚，耕田捕暋７訝瘴薰Γ右手空虛。通《屯》。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>艮為雀，艮手故曰探、曰捕。坤為魚、為田，震為耕夫，探雀得魚，耕田得暎二者皆必無之事，故曰無功。艮為日，兌右坤虛。○空虛，汲古作虛空，依宋元本。</p><h3 id="坎之震" tabindex="-1">坎之震 <a class="header-anchor" href="#坎之震" aria-label="Permalink to “坎之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>東行飲酒，與喜相抱。福為吾家，利來從父。水澤之徒，望邑而處。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為東，坎為酒，震口故曰飲酒。震為喜，艮手為抱，正反艮故曰相抱。艮為家，震為父，伏巽為利。坎為水，艮為望、為邑。○父，汲古作母，從宋元本。</p><h3 id="坎之艮" tabindex="-1">坎之艮 <a class="header-anchor" href="#坎之艮" aria-label="Permalink to “坎之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>妄怒失精，自令畏悔。忪忪之懼，君子無咎。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>震為怒，坎為畏懼，艮為君子。○第三句汲古作怡怡之歡，依宋元本。</p><h3 id="坎之漸" tabindex="-1">坎之漸 <a class="header-anchor" href="#坎之漸" aria-label="Permalink to “坎之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>白雲如帶，往往來處。飛風送迎，大雹將下。擊我禾稼，僵死不起。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>巽為白、為帶，坎為雲，巽進退故曰往來、曰送迎。艮為雹、為擊，巽為禾稼，坎陷故曰僵。○來，宋元本作旗，依汲古。</p><h3 id="坎之歸妹" tabindex="-1">坎之歸妹 <a class="header-anchor" href="#坎之歸妹" aria-label="Permalink to “坎之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>南至之日，陽消不息。北風烈寒，萬物藏伏。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>離為南、為日，曰南至、冬至，純陰極寒，故曰陽消不息。伏巽互坎，故曰北風。坎為寒。為伏，震為萬物，故曰萬物藏伏。</p><h3 id="坎之豐" tabindex="-1">坎之豐 <a class="header-anchor" href="#坎之豐" aria-label="Permalink to “坎之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>火中仲夏，鴻雁解舍。體重難移，未能高舉。君子顯名，不失其譽。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>《月令》：&quot;季夏之月，昬火中&quot;，火，心星也。仲當為季，火謂鶉火，屬南方。離為星、為火、為夏，伏艮為季，故曰季夏。震為鴻雁，中互大坎故曰難移，故不能高舉。伏艮為君子、為名譽。解舍，言天暑而棄其巢也。○舉，宋元本作舞，解作來，均依汲古。季夏，各本皆作仲夏，與《月令》不合，定為訛字。</p><h3 id="坎之旅" tabindex="-1">坎之旅 <a class="header-anchor" href="#坎之旅" aria-label="Permalink to “坎之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>北行出門，履蹈躓顛。踒足據塗，污我襦褲。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>伏《節》。坎北震行，艮門，故曰北行出門。震為履蹈，坎為蹇，故曰躓顛、曰踒足。躓踒，皆跌也。坎為污，震為襦褲。</p><h3 id="坎之巽" tabindex="-1">坎之巽 <a class="header-anchor" href="#坎之巽" aria-label="Permalink to “坎之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>輕車醊祖，疾風暴起。促亂祭器，飛陽鼓舞。明神降佑，道無害寇。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>兼用《震》象，詳《豫》之《大畜》。○疾，宋元本作焱，依汲古。佑，元本作佑。鼓舞，宋元本作錯華，均依汲古。</p><h3 id="坎之兌" tabindex="-1">坎之兌 <a class="header-anchor" href="#坎之兌" aria-label="Permalink to “坎之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>酒為歡伯，除憂來樂。福喜入門，與君相索，使我有得。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏《艮》。互坎為酒，震為歡、為伯，《酒譜》：&quot;昔人謂酒為歡伯&quot;。坎為憂，艮為門，震為福喜、為君，艮為求，正反艮故曰相索。艮為我。○得，宋元本作德，依汲古。</p><h3 id="坎之渙" tabindex="-1">坎之渙 <a class="header-anchor" href="#坎之渙" aria-label="Permalink to “坎之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>三足孤烏，靈明督郵。司過罰惡，自賊其家，毀敗為憂。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>《五行志》：&quot;日中有三足烏&quot;，震為足，數三，故曰三足。為黔啄，故曰烏。艮為龜，故曰督郵。詳《小畜》之《未濟》。震為郵。○靈明，汲古作虛鳴，依宋元本。督郵，為郡督察官，自西漢至魏晉皆有之，陶淵明不肯為督郵折腰者是也。</p><h3 id="坎之節" tabindex="-1">坎之節 <a class="header-anchor" href="#坎之節" aria-label="Permalink to “坎之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>三河俱合，水怒涌躍。壞我王屋，民飢於食。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《頤》。節中互頤，故詞同。○涌，宋本、汲古作踴，茲依元本。</p><h3 id="坎之中孚" tabindex="-1">坎之中孚 <a class="header-anchor" href="#坎之中孚" aria-label="Permalink to “坎之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>南行棗園，惡虎畏班。執火銷金，使我無患。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為南，艮為果、為園、為虎、為班。班，亦虎也，楚人謂虎為班。惡，憎也。艮為火、為手，故曰執火。艮為金、為我，虎為金精，以火銷金，故無虎患。○金，汲古作鋒，艮為刀鋒亦合，今依宋元本。</p><h3 id="坎之小過" tabindex="-1">坎之小過 <a class="header-anchor" href="#坎之小過" aria-label="Permalink to “坎之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>求鹿過山，與利為怨。暗龍不言，誰知其歡歡。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為求、為山，震為鹿，鹿在山外，故曰過山。巽為利，兌為耳、為昧，故暗聾。震言艮止故不言。○聾，汲古訛襲，依汲古。</p><h3 id="坎之既濟" tabindex="-1">坎之既濟 <a class="header-anchor" href="#坎之既濟" aria-label="Permalink to “坎之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>行旅困蹴，失明守宿。囹圄之憂，啟蟄出游。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《坎》象。震為行旅，艮止坎陷故曰困。坎為宿、為隱伏，故曰失明守宿。坎為囹圄、為憂、為蟄，震出故曰啟蟄出游。○蟄，宋元本作執，依汲古。</p><h3 id="坎之未濟" tabindex="-1">坎之未濟 <a class="header-anchor" href="#坎之未濟" aria-label="Permalink to “坎之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>據棘履杞，跌刺為憂。夫婦不和，亂我良家。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用《坎》象。坎為棘、為杞、為刺、為夫，離為婦，婦前夫後故曰不和。○杞，宋元本作危，今依汲古。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
